//! The text of [`super::CLIENT_FILE`]: one method of `JobClient` per call, taking and returning
//! the messages of `js-proto`, and the reader of a streamed answer when a call streams.

use super::surface::{Rpc, Surface};
use super::words::{snake, upper_camel};

/// The comment that opens both generated files.
pub fn header(surface: &Surface) -> String {
    format!(
        "// Generated by `cargo xtask gen-job-surface` from the descriptor set of `{}.{}`.\n// Do not edit: change the `.proto` files and run the verb again (docs/job-surface.md).\n\n#![cfg_attr(rustfmt, rustfmt::skip)]\n",
        surface.package, surface.service
    )
}

/// The Rust module of `js-proto` that holds the messages of `package`: its last part
/// (`jobscheduler.v1` is `v1`).
fn module(package: &str) -> &str {
    package.rsplit('.').next().unwrap_or(package)
}

/// The Rust path prost gives the message `full` (a full name in `package`): a nested
/// message is in the module of each message around it (`Outer.Inner` is `outer::Inner`),
/// and every name is spelt as prost spells it (`HTTPRequest` is `HttpRequest`).
fn type_path(package: &str, full: &str) -> String {
    let local = full
        .strip_prefix(package)
        .unwrap_or(full)
        .trim_start_matches('.');
    let mut parts: Vec<&str> = local.split('.').collect();
    let name = parts.pop().unwrap_or_default();
    let modules: Vec<String> = parts.iter().map(|part| snake(&upper_camel(part))).collect();
    let path: Vec<String> = std::iter::once(module(package).to_owned())
        .chain(modules)
        .chain(std::iter::once(upper_camel(name)))
        .collect();
    path.join("::")
}

/// The text of [`super::CLIENT_FILE`] for `surface`.
pub fn render(surface: &Surface) -> String {
    let streams = surface.rpcs.iter().any(|rpc| rpc.server_streaming);
    let mut out = header(surface);
    out.push_str(&format!(
        "\nuse js_proto::{};\n\nuse super::{{JobClient, JobError}};\n\nimpl JobClient {{\n",
        module(&surface.package)
    ));
    let methods: Vec<String> = surface
        .rpcs
        .iter()
        .map(|rpc| method(surface, rpc))
        .collect();
    out.push_str(&methods.join("\n"));
    out.push_str("}\n");
    let replies = match streams {
        true => REPLIES,
        false => "",
    };
    out.push_str(replies);
    out
}

/// The reader of a streamed answer, rendered when a call streams.
const REPLIES: &str = "
/// The answers of a call the server streams, read one at a time.
pub struct Replies<T> {
    stream: tonic::Streaming<T>,
    base: String,
    token: String,
}

impl<T> Replies<T> {
    /// The next answer, or `None` once the server has ended the stream. The request was
    /// written, so a failure is never [`JobError::NotSent`] for a reason of the network.
    pub async fn next(&mut self) -> Option<Result<T, JobError>> {
        let next = self.stream.message().await.transpose();
        next.map(|answer| answer.map_err(|status| super::error::classify(&self.base, &self.token, true, &status)))
    }
}
";

/// The method of one call.
fn method(surface: &Surface, rpc: &Rpc) -> String {
    let name = snake(&rpc.name);
    let request = type_path(&surface.package, &rpc.request.name);
    let response = type_path(&surface.package, &rpc.response);
    let doc: String = rpc.doc.iter().map(|line| doc_line(line)).collect();
    let retry: String = rpc
        .retry_key
        .iter()
        .map(|key| retry_doc(&key.field.join(".")))
        .collect();
    let (returns, answer) = match rpc.server_streaming {
        true => (
            format!("Replies<{response}>"),
            "answer.map(|stream| Replies { stream: stream.into_inner(), base: self.base.clone(), token: self.token.clone() })",
        ),
        false => (response, "answer.map(tonic::Response::into_inner)"),
    };
    format!(
        "{doc}{retry}    pub async fn {name}(&mut self, request: {request}) -> Result<{returns}, JobError> {{\n        let (attempt, request) = self.begin(request);\n        let answer = tokio::time::timeout(self.limit, self.service.{name}(request)).await;\n        answer.map_err(|_| self.timed_out(attempt)).and_then(|answer| {answer}.map_err(|status| self.classify(attempt, &status)))\n    }}\n"
    )
}

/// One line of a method's documentation.
fn doc_line(line: &str) -> String {
    match line.is_empty() {
        true => "    ///\n".to_owned(),
        false => format!("    /// {line}\n"),
    }
}

/// The paragraph a call idempotent on the id field `field` adds to its method's docs.
fn retry_doc(field: &str) -> String {
    format!(
        "    ///\n    /// After [`JobError::MayHaveActed`], sending the same request again, with the same\n    /// non-empty `{field}`, is safe: the service answers from what the first request made. An empty id\n    /// lets the service mint one, so a repeat of it may make a second job. The client never\n    /// chooses or changes the id; the caller does.\n"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Asserts the Rust path of a message as prost spells it: a top-level message, a nested
    /// one in the module of the message around it, and a name prost respells.
    #[test]
    fn message_paths_are_spelt_as_prost_spells_them() {
        assert_eq!(
            type_path("jobscheduler.v1", "jobscheduler.v1.GetJobRequest"),
            "v1::GetJobRequest"
        );
        assert_eq!(
            type_path("p.v2", "p.v2.Outer.HTTPInner"),
            "v2::outer::HttpInner"
        );
    }
}
